  patient_id?: number | null;
  admission_id?: number | null;
  reason: "Admission" | "ChangeOfWard" | "ChangeOfCondition" | "Procedure" | "OnRequest";
  /** ChangeOfWard: the move it answers (GET /admissions/{id}/transfers) */
  transfer_id?: number | null;
  /** The ward priced (default: the admission's ward) */
